class Solution {
public:
 vector<int> findAllPeople(int n,vector<vector<int>>& meetings,int firstPerson){
  sort(meetings.begin(),meetings.end(),[](const vector<int>&a,const vector<int>&b){return a[2]<b[2];});
  vector<char> knows(n,false);knows[0]=knows[firstPerson]=true;
  for(int i=0;i<(int)meetings.size();){
   int j=i;unordered_map<int,vector<int>> adj;
   while(j<(int)meetings.size() && meetings[j][2]==meetings[i][2]){
    int a=meetings[j][0],b=meetings[j][1];adj[a].push_back(b);adj[b].push_back(a);++j;
   }
   queue<int> q;unordered_set<int> seen;
   for(auto& p:adj) if(knows[p.first]){q.push(p.first);seen.insert(p.first);}
   while(!q.empty()){
    int u=q.front();q.pop();knows[u]=true;
    for(int v:adj[u]) if(seen.insert(v).second)q.push(v);
   }
   i=j;
  }
  vector<int> ans;for(int i=0;i<n;++i)if(knows[i])ans.push_back(i);return ans;
 }
};
